<template>
 <main class="pg5-workspace" :class="{'pg5-workspace--editing':propsOpen&&propsMobile}">
  <header class="pg5-header"><Button class="pg5-nav-toggle" variant="text" icon-name="menu" icon-only aria-label="打开组件导航" @click="navOpen=true"/><div class="pg5-brand"><strong>KnowFlow</strong><h1 aria-label="组件开发中心 V6">{{navMobile?'组件中心':'组件开发中心'}} <small>V6</small></h1></div><Input ref="search" v-model="query" label="搜索组件" placeholder="组件、Props、规范 · ⌘K" prefix-icon-name="search"/><Select v-model="theme" aria-label="预览主题" :options="[{value:'light',label:'浅色主题'},{value:'dark',label:'深色主题'}]"/><Button size="sm" variant="text" aria-label="质量中心" @click="mode=mode==='quality'?'components':'quality'">{{navMobile?'质量':'质量中心'}}</Button><Button size="sm" variant="text" aria-label="Design Tokens" @click="mode=mode==='tokens'?'components':'tokens'">{{navMobile?'规范':'Design Tokens'}}</Button></header>
  <div class="pg5-toolbar"><span>{{entries.length}}条目 · {{realCount}}真实 · {{demoCount}}Demo · {{entries.length-realCount-demoCount}}未实现</span><div class="pg5-row"><Button v-if="mode!=='components'" size="sm" variant="secondary" @click="mode='components'">返回组件</Button><Button v-if="propsMobile&&mode==='components'" size="sm" variant="secondary" icon-name="settings" @click="propsOpen=true">调试属性</Button><Button size="sm" variant="text" icon-name="link" @click="copyLink">{{linkNotice}}</Button></div></div>
  <div class="pg5-layout" :class="{'pg5-layout--wide':mode!=='components'}">
   <aside v-if="!navMobile" class="pg5-navigation"><div class="pg5-session-links"><Button size="sm" variant="text" @click="navFilter=navFilter==='recent'?'all':'recent'">最近</Button><Button size="sm" variant="text" @click="navFilter=navFilter==='favorite'?'all':'favorite'">收藏 {{favorites.length}}</Button></div><Select v-model="implementationFilter" aria-label="组件实现状态" :options="implementationOptions"/><ComponentNavigation :entries="visibleEntries" :selected="current.id" :query="query" @select="selectComponent"/></aside>
   <div v-if="mode==='tokens'" class="pg5-main"><TokenCenter/></div>
   <div v-else-if="mode==='quality'" class="pg5-main"><QualityDashboard :entries="entries" :records="measurements" @select="locate"/></div>
   <section v-else class="pg5-main" aria-label="组件工作区">
    <header class="pg5-component-header"><div class="pg5-row"><h2>{{current.title}}</h2><code>{{current.name}}</code><span class="pg5-implementation">{{current.implementationStatus}}</span><Button size="sm" variant="text" :aria-label="favorites.includes(current.id)?'取消收藏当前组件':'收藏当前组件'" @click="toggleFavorite">{{favorites.includes(current.id)?'已收藏':'收藏'}}</Button></div><p>{{current.description}}</p><details class="pg5-source"><summary>源码与分类</summary><code>{{current.sourcePath}}</code><p>{{current.category}}</p></details></header>
    <div class="pg5-storybar"><Select :model-value="activeStory.storyId" aria-label="选择Story" :options="ownStories.map(s=>({value:s.storyId,label:s.title}))" @update:model-value="chooseStory(String($event))"/><span>{{activeStory.category}}</span><Button size="sm" variant="text" @click="reset">Reset</Button><Button size="sm" variant="text" @click="focusPreview">Focus Test</Button><Button size="sm" variant="text" @click="fullscreen=!fullscreen">{{fullscreen?'退出全屏':'Fullscreen'}}</Button></div>
    <div class="pg5-tabs" role="tablist" aria-label="组件文档" @keydown="tabKey"><button v-for="(tab,i) in docTabs" :id="'pg5-tab-'+i" :key="tab" role="tab" :aria-selected="docTab===tab" :tabindex="docTab===tab?0:-1" aria-controls="pg5-document-panel" @click="docTab=tab">{{tab}}</button></div>
    <div id="pg5-document-panel" role="tabpanel" :aria-labelledby="'pg5-tab-'+docTabs.indexOf(docTab)" class="pg5-tab-content">
     <div v-show="docTab==='Preview'" class="pg5-preview-workspace"><div class="pg5-canvas-tools"><Select v-model="viewport" aria-label="预览容器宽度" :options="[{value:'auto',label:'Desktop'},{value:'768',label:'Tablet · 768'},{value:'390',label:'Mobile · 390'}]"/><Select v-model="background" aria-label="预览背景" :options="[{value:'card',label:'白色/主题表面'},{value:'muted',label:'浅灰表面'},{value:'dark',label:'深色画布'}]"/><Button size="sm" variant="text" @click="docTab='Examples'">查看代码</Button><Button size="sm" variant="text" @click="copyCode">{{copyNotice}}</Button><Button size="sm" variant="text" @click="rightTab='Inspector';propsMobile&&(propsOpen=true)">查看尺寸</Button></div>
      <div :class="['pg5-stage',{'pg5-stage--fullscreen':fullscreen}]" :style="canvasStyle"><Button v-if="fullscreen" @click="fullscreen=false">退出全屏</Button><div class="pg5-canvas" :style="{width:viewport==='auto'?'100%':viewport+'px'}"><ComponentPreview :key="current.id+':'+activeStory.storyId+':'+generation" ref="preview" :entry="current" :settings="settings" :size="buttonSize" :variant="buttonVariant" :disabled="!!settings.disabled" :loading="!!settings.loading||!!settings.busy" :icon="!!settings.iconName" :right-icon="settings.iconPosition==='right'" :error="!!settings.error" :label="String(settings.label||'新增内容')" @event="record"/></div></div><p class="pg5-hint">{{activeStory.description}} 容器宽度模拟不等于真实设备验收。</p>
     </div>
     <QualityDashboard v-if="docTab==='Quality'" :entries="[current]" :records="measurements" @select="locate"/>
     <ComponentDocs v-else-if="docTab!=='Preview'" :entry="current" :story="activeStory" :tab="docTab" :example="example"/>
    </div>
   </section>
   <aside v-if="mode==='components'&&!propsMobile" class="pg5-side" aria-label="属性与检查"><div class="pg5-side-tabs" role="tablist" aria-label="调试面板"><button v-for="tab in rightTabs" :key="tab" role="tab" :aria-selected="rightTab===tab" @click="rightTab=tab">{{tab}}</button></div><div class="pg5-side-body"><PlaygroundProperties :key="current.id+activeStory.storyId+generation" v-show="rightTab==='Properties'" :entry="current" :settings="settings" @update="update" @reset="reset"/><StyleInspector v-show="rightTab==='Inspector'" :host="preview?.host" :entry="current" :story-id="activeStory.storyId" :size="buttonSize" :revision="revision" :locate-element="locateElement" @measurement="receiveMeasurements"/><EventLog v-if="rightTab==='Events'" :events="events" @clear="events=[]"/></div></aside>
  </div>
  <PlaygroundDrawer v-if="navMobile" :open="navOpen" title="组件目录" side="right" @close="navOpen=false"><Input v-model="query" label="搜索组件目录" placeholder="名称或Props"/><Select v-model="implementationFilter" aria-label="组件实现状态" :options="implementationOptions"/><ComponentNavigation :entries="visibleEntries" :selected="current.id" :query="query" @select="selectComponent"/></PlaygroundDrawer>
  <PlaygroundDrawer v-if="propsMobile" :open="propsOpen" title="属性与检查" @close="propsOpen=false"><div class="pg5-side-tabs" role="tablist" aria-label="抽屉调试面板"><button v-for="tab in rightTabs" :key="tab" role="tab" :aria-selected="rightTab===tab" @click="rightTab=tab">{{tab}}</button></div><PlaygroundProperties :key="current.id+activeStory.storyId+generation" v-if="rightTab==='Properties'" :entry="current" :settings="settings" @update="update" @reset="reset"/><StyleInspector v-else-if="rightTab==='Inspector'" :host="preview?.host" :entry="current" :story-id="activeStory.storyId" :size="buttonSize" :revision="revision" :locate-element="locateElement" @measurement="receiveMeasurements"/><EventLog v-else :events="events" @clear="events=[]"/></PlaygroundDrawer>
 </main>
</template>
<script setup lang="ts">
import {computed,ref,reactive,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Button from '@/components/ui/Button.vue'
import Input from '@/components/ui/Input.vue'
import Select from '@/components/ui/Select.vue'
import ComponentPreview from '@/dev/ComponentPreview.vue'
import StyleInspector from '@/dev/StyleInspector.vue'
import ComponentNavigation from '@/dev/ComponentNavigation.vue'
import ComponentDocs from '@/dev/ComponentDocs.vue'
import PlaygroundProperties from '@/dev/PlaygroundProperties.vue'
import PlaygroundDrawer from '@/dev/PlaygroundDrawer.vue'
import EventLog from '@/dev/EventLog.vue'
import TokenCenter from '@/dev/TokenCenter.vue'
import QualityDashboard from '@/dev/QualityDashboard.vue'
import type {MeasurementRecord} from '@/dev/quality'
import {entries,searchEntries} from '@/dev/registry'
import {stories,resolveStory,storyDefaults} from '@/dev/stories'
import {createExample} from '@/dev/code-examples'
import {safeFixtureLog} from '@/dev/safe-fixture-log'
import '@/dev/playground.css'
import '@/dev/playground-v5.css'
const implementationFilter=ref('ALL'),implementationOptions=[{value:'ALL',label:'全部实现状态'},...['PRODUCTION','DEMO_ONLY','PLANNED','DEPRECATED'].map(value=>({value,label:value}))]
const router=useRouter(),route=useRoute(),query=ref(''),selected=ref('Button'),selectedStory=ref('basic'),mode=ref('components'),docTab=ref('Preview'),rightTab=ref('Properties'),navFilter=ref('all'),navOpen=ref(false),propsOpen=ref(false),generation=ref(0),revision=ref(0),fullscreen=ref(false),viewport=ref('auto'),background=ref('card'),settings=reactive<Record<string,any>>({}),copyNotice=ref('复制代码'),linkNotice=ref('复制Story链接'),preview=ref<InstanceType<typeof ComponentPreview>>(),search=ref<InstanceType<typeof Input>>(),recent=ref<string[]>([]),favorites=ref<string[]>([]),measurements=ref<MeasurementRecord[]>([]),locateElement=ref('')
const navMobile=ref(window.innerWidth<760),propsMobile=ref(window.innerWidth<1180),docTabs=['Preview','Examples','API','States','Design Specs','Accessibility','Quality','业务场景'],rightTabs=['Properties','Inspector','Events']
const originalTheme=document.documentElement.getAttribute('data-theme'),originalScheme=document.documentElement.style.colorScheme,theme=ref(originalTheme==='dark'?'dark':'light')
const current=computed(()=>entries.find(e=>e.id===selected.value)||entries[0]!),ownStories=computed(()=>stories.filter(s=>s.componentId===current.value.id)),activeStory=computed(()=>ownStories.value.find(s=>s.storyId===selectedStory.value)||ownStories.value[0]!),visibleEntries=computed(()=>searchEntries(query.value).filter(e=>implementationFilter.value==='ALL'||e.production.status===implementationFilter.value).filter(e=>navFilter.value==='recent'?recent.value.includes(e.id):navFilter.value==='favorite'?favorites.value.includes(e.id):true)),realCount=entries.filter(e=>e.implementationStatus==='已接入真实组件').length,demoCount=entries.filter(e=>e.implementationStatus==='仅有内部演示').length
const buttonSize=computed(()=>(['sm','md','lg'].includes(String(settings.size))?settings.size:'md') as 'sm'|'md'|'lg'),buttonVariant=computed(()=>(['primary','secondary','outline','ghost','text','danger'].includes(String(settings.variant))?settings.variant:'primary') as 'primary'|'secondary'|'outline'|'ghost'|'text'|'danger'),example=computed(()=>createExample(current.value,settings)),events=ref<{time:string;name:string;value:string}[]>([]),canvasStyle=computed(()=>({background:background.value==='dark'?'var(--kf-gray-950, black)':`var(--kf-${background.value})`}))
function applyUrl(){const result=resolveStory(entries,stories,route?.query.component,route?.query.story);selected.value=result.entry!.id;selectedStory.value=result.story!.storyId}
function syncUrl(){if(!router)return;const component=current.value.id.toLowerCase(),story=activeStory.value.storyId;if(route?.query.component===component&&route.query.story===story)return;void router.push({path:'/dev/ui-components',query:{component,story}})}
function selectComponent(id:string){selected.value=id;selectedStory.value='basic';docTab.value='Preview';mode.value='components';navOpen.value=false;fullscreen.value=false;syncUrl()}
function chooseStory(id:string){selectedStory.value=id;docTab.value='Preview';syncUrl()}
function reset(){for(const key of Object.keys(settings))delete settings[key];Object.assign(settings,storyDefaults(current.value,activeStory.value));generation.value++;events.value=[];revision.value++;copyNotice.value='复制代码';locateElement.value=''}
function update(name:string,value:unknown){settings[name]=value;record('prop:'+name,value)}
function record(name:string,value:unknown){events.value=[{time:new Date().toLocaleTimeString(),name,value:safeFixtureLog(value)},...events.value].slice(0,40);revision.value++}
function receiveMeasurements(records:MeasurementRecord[]){const map=new Map(measurements.value.map(r=>[[r.componentId,r.storyId,r.element,r.property,r.category||'Visual'].join('|'),r]));for(const r of records)map.set([r.componentId,r.storyId,r.element,r.property,r.category||'Visual'].join('|'),r);measurements.value=[...map.values()].slice(-2000)}
async function locate(componentId:string,storyId:string,element?:string){const result=resolveStory(entries,stories,componentId,storyId);selected.value=result.entry!.id;selectedStory.value=result.story!.storyId;docTab.value='Preview';mode.value='components';syncUrl();await nextTick();locateElement.value=element||'';rightTab.value='Inspector';if(propsMobile.value)propsOpen.value=true}
function toggleFavorite(){favorites.value=favorites.value.includes(current.value.id)?favorites.value.filter(id=>id!==current.value.id):[...favorites.value,current.value.id]}
async function copyCode(){try{await navigator.clipboard.writeText(example.value);copyNotice.value='已复制'}catch{copyNotice.value='剪贴板不可用'}}
async function copyLink(){const url=new URL('/dev/ui-components',location.origin);url.searchParams.set('component',current.value.id.toLowerCase());url.searchParams.set('story',activeStory.value.storyId);try{await navigator.clipboard.writeText(url.href);linkNotice.value='链接已复制'}catch{linkNotice.value='剪贴板不可用'}}
async function focusPreview(){docTab.value='Preview';await nextTick();preview.value?.host?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),[tabindex]:not([tabindex="-1"])')?.focus();record('focus-test','仅移动真实焦点；视觉/读屏未自动认证')}
function tabKey(event:KeyboardEvent){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const i=docTabs.indexOf(docTab.value),next=event.key==='Home'?0:event.key==='End'?docTabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+docTabs.length)%docTabs.length;docTab.value=docTabs[next]!;document.getElementById('pg5-tab-'+next)?.focus()}
function resize(){navMobile.value=window.innerWidth<760;propsMobile.value=window.innerWidth<1180;if(!navMobile.value)navOpen.value=false;if(!propsMobile.value)propsOpen.value=false}
function key(event:KeyboardEvent){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();event.stopImmediatePropagation();search.value?.$el?.querySelector('input')?.focus()}if(event.key==='Escape')fullscreen.value=false}
watch(()=>[current.value.id,activeStory.value.storyId],()=>{reset();recent.value=[current.value.id,...recent.value.filter(id=>id!==current.value.id)].slice(0,8)},{immediate:true})
watch(()=>[route?.query.component,route?.query.story],applyUrl,{immediate:true})
watch(propsOpen,async open=>{if(open){docTab.value='Preview';await nextTick();preview.value?.host?.scrollIntoView({block:'start',behavior:'instant'})}})
watch(theme,value=>{document.documentElement.dataset.theme=value;document.documentElement.style.colorScheme=value;revision.value++})
onMounted(()=>{window.addEventListener('keydown',key,true);window.addEventListener('resize',resize)})
onBeforeUnmount(()=>{window.removeEventListener('keydown',key,true);window.removeEventListener('resize',resize);if(originalTheme===null)document.documentElement.removeAttribute('data-theme');else document.documentElement.setAttribute('data-theme',originalTheme);document.documentElement.style.colorScheme=originalScheme})
</script>
